FactoryBot.define do
  factory :user_api_token do
    user
    sequence(:name) { |n| "Token #{n}" }

    # The plain text key is generated by the model before validation and is
    # never persisted, so it is only readable from the object which was built.
    # FactoryBot returns that same object which means `create(:user_api_token).plain_key`
    # gives specs something to send in the X-Postal-API-Key header.
    trait :expired do
      expires_at { 1.hour.ago }
    end

    trait :revoked do
      revoked_at { Time.now }
    end
  end
end
